import collections

def solve():
    def get_possible_moves(board, n):
        moves = []
        # Trominoes: (r, c), (r+1, c), (r+1, c+1)
        for r in range(n - 1):
            for c in range(n - 1):
                if not board[r][c] and not board[r+1][c] and not board[r+1][c+1]:
                    moves.append(('T', r, c))
        # Row clearing
        for r in range(n):
            if all(board[r][c] for c in range(n)):
                moves.append(('R', r))
        # Column clearing
        for c in range(n):
            if all(board[r][c] for r in range(n)):
                moves.append(('C', c))
        return moves

    def apply_move(board, move, n):
        new_board = [row[:] for row in board]
        if move[0] == 'T':
            r, c = move[1], move[2]
            new_board[r][c] = 1
            new_board[r+1][c] = 1
            new_board[r+1][c+1] = 1
        elif move[0] == 'R':
            r = move[1]
            for c in range(n):
                new_board[r][c] = 0
        elif move[0] == 'C':
            c = move[1]
            for r in range(n):
                new_board[r][c] = 0
        return new_board

    def board_to_tuple(board):
        return tuple(tuple(row) for row in board)

    for n in range(2, 6):
        start_board = [[0]*n for _ in range(n)]
        start_tuple = board_to_tuple(start_board)
        queue = collections.deque([(start_tuple, 0)])
        visited = {start_tuple}

        possible = False
        while queue:
            curr_tuple, dist = queue.popleft()
            curr_board = [list(row) for row in curr_tuple]

            moves = get_possible_moves(curr_board, n)
            for move in moves:
                next_board = apply_move(curr_board, move, n)
                next_tuple = board_to_tuple(next_board)
                if dist + 1 > 0 and next_tuple == start_tuple:
                    possible = True
                    break
                if next_tuple not in visited:
                    visited.add(next_tuple)
                    queue.append((next_tuple, dist + 1))
            if possible:
                break
        print(f"n={n}, possible={possible}")

