import numpy as np

def check_xor_possible(n):
    # Variables: a_{r,c} for r,c in 0..n-2, b_i for i in 0..n-1, d_j for j in 0..n-1
    # Total variables: (n-1)**2 + 2*n
    num_vars = (n-1)**2 + 2*n
    matrix = np.zeros((n*n, num_vars), dtype=int)

    var_idx = 0
    # L-trominoes
    for r in range(n-1):
        for c in range(n-1):
            matrix[r*n + c, var_idx] = 1
            matrix[(r+1)*n + c, var_idx] = 1
            matrix[(r+1)*n + (c+1), var_idx] = 1
            var_idx += 1
    # Rows
    for r in range(n):
        for c in range(n):
            matrix[r*n + c, var_idx] = 1
        var_idx += 1
    # Cols
    for c in range(n):
        for r in range(n):
            matrix[r*n + c, var_idx] = 1
        var_idx += 1

    # Rank in GF(2)
    def gf2_rank(mat):
        mat = mat.copy() % 2
        rows, cols = mat.shape
        rank = 0
        for c in range(cols):
            if rank >= rows: break
            # Find pivot
            pivot = -1
            for r in range(rank, rows):
                if mat[r, c]:
                    pivot = r
                    break
            if pivot != -1:
                mat[[rank, pivot]] = mat[[pivot, rank]]
                for r in range(rows):
                    if r != rank and mat[r, c]:
                        mat[r] = (mat[r] + mat[rank]) % 2
                rank += 1
        return rank

    rank = gf2_rank(matrix)
    return num_vars > rank

