import random

def solve_n_random(n, max_steps=100000):
    board = [[0]*n for _ in range(n)]

    for step in range(max_steps):
        moves = []
        # Trominoes
        for r in range(n - 1):
            for c in range(n - 1):
                if not board[r][c] and not board[r+1][c] and not board[r+1][c+1]:
                    moves.append(('T', r, c))
        # Rows
        for r in range(n):
            if all(board[r][c] for c in range(n)):
                moves.append(('R', r))
        # Cols
        for c in range(n):
            if all(board[r][c] for r in range(n)):
                moves.append(('C', c))

        if not moves:
            # Stuck, restart
            board = [[0]*n for _ in range(n)]
            continue

        move = random.choice(moves)
        if move[0] == 'T':
            r, c = move[1], move[2]
            board[r][c] = 1
            board[r+1][c] = 1
            board[r+1][c+1] = 1
        elif move[0] == 'R':
            r = move[1]
            for c in range(n):
                board[r][c] = 0
        elif move[0] == 'C':
            c = move[1]
            for r in range(n):
                board[r][c] = 0

        if all(all(cell == 0 for cell in row) for row in board) and step > 0:
            return True

    return False

